/**
 * @param {string} carId
 * @param {'high'|'mid'|'low'} [bopCategory='high']
 */
export function getGr3Measurable(carId, bopCategory = "high") {
  const table = GR3_MEASURABLE_171.bop?.[bopCategory];
  if (!table) return null;
  return table[carId] ?? null;
}
